<?php use App\Models\Content;use App\Services\Navigation;?>
<footer id="contact"><div class="container"><div class="footer-grid"><div class="col"><div class="footer-brand"><?php if(setting('footer_logo')):?><?=media_img(setting('footer_logo'),setting('company_name'),'footer-logo site-header-logo')?><?php else:?><h5><?=e(setting('company_name'))?></h5><?php endif?></div><p class="tagline"><?=e(setting('footer_description'))?></p><div class="social-row"><?php foreach(Content::published('social_links') as $social):?><a href="<?=e(cms_url($social['custom_url']))?>" aria-label="<?=e($social['title'])?>" target="_blank" rel="noopener noreferrer"><i class="<?=e($social['icon'])?>"></i></a><?php endforeach?></div></div>
<?php foreach(Content::published('footer_columns',"placement='main'") as $column):?><div class="col"><h6><?=e($column['title'])?></h6><?php if($column['content_mode']==='contact'):?><ul class="footer-contact"><?php if(setting('address')):?><li><i class="fa-solid fa-location-dot"></i><?php if(setting('map_link')):?><a href="<?=e(cms_url(setting('map_link')))?>" target="_blank" rel="noopener noreferrer"><?=nl2br(e(setting('address')))?></a><?php else:?><?=nl2br(e(setting('address')))?><?php endif?></li><?php endif?><?php if(setting('phone')):?><li><i class="fa-solid fa-phone"></i><a href="tel:<?=e(preg_replace('/[^+0-9]/','',setting('phone')))?>"><?=e(setting('phone'))?></a></li><?php endif?><?php if(setting('email')):?><li><i class="fa-regular fa-envelope"></i><a href="mailto:<?=e(setting('email'))?>"><?=e(setting('email'))?></a></li><?php endif?><?php if(setting('business_hours')):?><li><i class="fa-regular fa-clock"></i><?=nl2br(e(setting('business_hours')))?></li><?php endif?></ul><?php else:$links=$column['content_mode']==='manual'?Content::published('footer_menu_items','column_id=?',[$column['id']],(int)$column['display_limit']):array_map(fn($r)=>$r+['link_type'=>'custom','custom_url'=>Navigation::recordUrl($column['content_mode'],$r),'target'=>'_self'],Content::published($column['content_mode'],'1=1',[],(int)$column['display_limit']));?><ul><?php foreach($links as $link):$href=Navigation::link($link);if($href===null)continue;?><li><a href="<?=e(cms_url($href))?>" target="<?=e($link['target'])?>" rel="noopener noreferrer"><?=e($link['title'])?></a></li><?php endforeach?></ul><?php endif?></div><?php endforeach?></div><div class="footer-bottom"><span><?=e(str_replace(['{year}','{company}'],[gmdate('Y'),setting('company_name')],setting('copyright')))?></span><?php cms_view('public/footer-bottom-links');?><span><?=e(setting('developer_credit'))?></span></div></div></footer>
